package com.kartyavya.report.integration; import com.kartyavya.contracts.AccessContracts.*; import org.springframework.cloud.openfeign.FeignClient; import org.springframework.web.bind.annotation.*; @FeignClient(name="access-admin-service",configuration=InternalFeignConfig.class) public interface AccessClient{@GetMapping("/internal/users/{id}/contact")UserContact user(@PathVariable Long id);@GetMapping("/internal/departments/{id}")DepartmentInfo department(@PathVariable Long id);@GetMapping("/internal/departments/{id}/officers")OfficersResponse officers(@PathVariable Long id);@GetMapping("/internal/officers/{id}")OfficerInfo officer(@PathVariable Long id);@GetMapping("/internal/routing/resolve")RoutingResolution route(@RequestParam String category);@GetMapping("/internal/stats")java.util.Map<String,Long> stats();}
